import { createDraftStore } from './src/draft-store.js';
import { createReceiptArchive } from './src/receipt-archive.js';
function setup(onSaved = () => {}) {
  const callbacks = new Map(); let next = 0;
  const timers = { schedule(fn, delay) { assert.equal(delay, 120); const id = ++next; callbacks.set(id, fn); return id; }, cancel(id) { callbacks.delete(id); } };
  const store = createDraftStore(); const archive = createReceiptArchive();
  const documents = [], statuses = [], submissions = [];
  const workspace = createWorkspace({ store, archive, timers, onSaved, renderDocument: x => documents.push(x), renderStatus: x => statuses.push(x), renderSubmission: x => submissions.push(x) });
  return { callbacks, store, archive, documents, statuses, submissions, workspace, run() { const [id, fn] = callbacks.entries().next().value; callbacks.delete(id); fn(); } };
}
{
